package ai.novita.sandbox.core;
public class BuildStatus { @com.google.gson.annotations.SerializedName(value="templateID", alternate={"template_id"}) private String templateID; @com.google.gson.annotations.SerializedName(value="buildID", alternate={"build_id"}) private String buildID; private String status,message; private com.google.gson.JsonElement logs; @com.google.gson.annotations.SerializedName(value="logEntries", alternate={"log_entries","events"}) private java.util.List<BuildLogEntry> logEntries; private BuildFailureReason reason; public String getTemplateId(){return templateID;} public String getBuildId(){return buildID;} public String getStatus(){return status;} public String getMessage(){return message;} public String getLogs(){if(logs==null||logs.isJsonNull())return null;return logs.isJsonPrimitive()?logs.getAsString():logs.toString();} public java.util.List<BuildLogEntry> getLogEntries(){return logEntries;} public BuildFailureReason getReason(){return reason;} }
